import React, { useState, useEffect, useRef } from 'react';
import classes from './Slider.module.scss';
import slaiders from './Slid1.svg'

const Slider = () => {
  const images = [
    slaiders,
    slaiders,
    slaiders,
  ];

  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [transitioning, setTransitioning] = useState(false);

  const sliderTrackRef = useRef(null);

  const [slideWidth, setSlideWidth] = useState(776);
  const [sliderWidth, setSliderWidth] = useState(1500);
  const [slideMargin, setSlideMargin] = useState(20);

  useEffect(() => {
    const handleResize = () => {
      const container = document.querySelector(`.${classes.sliderContainer}`);

      if (container) {
        setSlideWidth(parseInt(getComputedStyle(container).getPropertyValue('--slide-width')) || 776);
        setSliderWidth(parseInt(getComputedStyle(container).getPropertyValue('--slider-width')) || 1500);
        setSlideMargin(parseInt(getComputedStyle(container).getPropertyValue('--slide-margin')) || 20);
      }
    };

    handleResize();

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  const goToImage = (index) => {
    if (transitioning) return;

    setTransitioning(true);
    setCurrentImageIndex(index);

    setTimeout(() => {
      setTransitioning(false);
    }, 300);
  };

  const getSlideStyle = (index) => {
    let style = classes.slide;
    const totalImages = images.length;
    let relationalPosition = (index - currentImageIndex + totalImages) % totalImages;

    if (relationalPosition === 0) {
      style = `${classes.slide} ${classes.activeSlide}`;
    } else if (relationalPosition === 1 || relationalPosition === totalImages - 1) {
      style = `${classes.slide} ${classes.adjacentSlide}`;
    } else {
      style = `${classes.slide} ${classes.hiddenSlide}`;
    }
    return style;
  };

  const handleSlideClick = (index) => {
    if (index === currentImageIndex) return;

    const nextIndex = (currentImageIndex + 1) % images.length;
    const prevIndex = (currentImageIndex - 1 + images.length) % images.length;

    if (index === nextIndex || index === prevIndex) {
      goToImage(index);
    }
  };

  const translateX = `calc(50% - ${currentImageIndex * (slideWidth + slideMargin)}px - ${slideWidth / 2}px)`;

  return (
    <div className={classes.sliderContainer}>
      <div
        className={classes.sliderTrack}
        ref={sliderTrackRef}
        style={{
          transform: `translateX(${translateX})`,
        }}
      >
        {images.map((image, index) => (
          <img
            key={index}
            src={image}
            alt={`Слайд ${index + 1}`}
            className={getSlideStyle(index)}
            onClick={() => handleSlideClick(index)}
          />
        ))}
      </div>
    </div>
  );
};

export default Slider;