import React, { useState, useEffect, useCallback } from 'react';
import MoviesData from '../../MoviesData';
import classes from './Favorite.module.scss';
import { useNavigate } from 'react-router-dom';

import heartRegular from '../../components/SectionFilm/heart-regular.png';
import heartSolid from '../../components/SectionFilm/heart-solid.png';

const Favorite = () => {
    const [favoriteMovies, setFavoriteMovies] = useState(() => {
        const savedFavorites = localStorage.getItem('favorites');
        try {
            return savedFavorites ? JSON.parse(savedFavorites) : [];
        } catch (error) {
            console.error("Error parsing favorites from localStorage:", error);
            return [];
        }
    });

    const [viewedMovies, setViewedMovies] = useState(() => {
        const savedViewed = localStorage.getItem('viewed');
        try {
            return savedViewed ? JSON.parse(savedViewed) : [];
        } catch (error) {
            console.error("Error parsing viewed from localStorage:", error);
            return [];
        }
    });
    const navigate = useNavigate();

    const setLocalStorage = useCallback((key, value) => {
        localStorage.setItem(key, JSON.stringify(value));
    }, []);

    const removeFromFavorites = useCallback((movieId) => {
        setFavorites(prevFavorites => {
            const updatedFavorites = prevFavorites.filter(id => id !== movieId);
            setLocalStorage('favorites', updatedFavorites);
            return updatedFavorites;
        });
    }, [setLocalStorage]);

    const setFavorites = useCallback((newFavorites) => {
        localStorage.setItem('favorites', JSON.stringify(newFavorites));
        setFavoriteMovies(newFavorites);
    }, []);

    const clearViewedMovies = useCallback(() => {
        localStorage.removeItem('viewed');
        setViewedMovies([]);
    }, [setViewedMovies]);


    const handleMovieClick = useCallback((movie) => {
        navigate('/MoviePage', { state: { movie } });
    }, [navigate]);

    const renderFavoriteMovie = useCallback((movie) => {
        if (!movie) {
            return null;
        }

        const handleFavoriteClick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            removeFromFavorites(movie.id);
        };

        return (
            <div key={movie.id} className={classes.moviePosterContainer}>
                <div onClick={() => handleMovieClick(movie)} style={{ cursor: 'pointer' }}>
                    <img
                        src={movie.src}
                        alt={movie.title}
                        className={classes.moviePoster}
                    />
                    <div className={classes.movieInfoOverlay}>
                        <div className={classes.movieDetails}>
                            <span className={classes.rating}>{movie.rating.toFixed(1)}</span>
                            <span className={classes.year}>{movie.year}, {movie.country}</span>
                            <span className={classes.duration}>{movie.duration} мин.</span>
                        </div>
                        <div className={classes.favoriteIcon} onClick={handleFavoriteClick}>
                            <img
                                src={heartSolid}
                                alt="Favorite"
                                className={classes.heartImage}
                            />
                        </div>
                    </div>
                </div>
                <button className={classes.removeButton} onClick={() => handleFavoriteClick(movie.id)}>
                    Удалить из избранного
                </button>
            </div>
        );
    }, [removeFromFavorites, handleMovieClick, heartSolid]);

    const renderViewedMovie = useCallback((movie) => {
        if (!movie) {
            console.log('renderViewedMovie - movie is null or undefined');
            return null;
        }
        console.log('renderViewedMovie - movie:', movie);

        const isFavorite = favoriteMovies.includes(movie.id);

        const handleFavoriteClick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            if (isFavorite) {
                removeFromFavorites(movie.id);
            } else {
                setFavorites([...favoriteMovies, movie.id]);
            }
        };

        return (
            <div key={movie.id} className={classes.moviePosterContainer}>
                <div onClick={() => handleMovieClick(movie)} style={{ cursor: 'pointer' }}>
                    <img
                        src={movie.src}
                        alt={movie.title}
                        className={classes.moviePoster}
                    />
                    <div className={classes.movieInfoOverlay}>
                        <div className={classes.movieDetails}>
                            <span className={classes.rating}>{movie.rating.toFixed(1)}</span>
                            <span className={classes.year}>{movie.year}, {movie.country}</span>
                            <span className={classes.duration}>{movie.duration} мин.</span>
                        </div>
                        <div className={classes.favoriteIcon} onClick={handleFavoriteClick}>
                            <img
                                src={isFavorite ? heartSolid : heartRegular}
                                alt="Favorite"
                                className={classes.heartImage}
                            />
                        </div>
                    </div>
                </div>
            </div>
        );
    }, [handleMovieClick, favoriteMovies, removeFromFavorites, setFavorites]);

    useEffect(() => {
        const savedViewed = localStorage.getItem('viewed');
        try {
            setViewedMovies(savedViewed ? JSON.parse(savedViewed) : []);
        } catch (error) {
            console.error("Error parsing viewed from localStorage:", error);
            setViewedMovies([]);
        }
    }, []);

    useEffect(() => {
        console.log('Favorite - viewedMovies:', viewedMovies);
    }, [viewedMovies]);


    const favoriteMovieObjects = MoviesData.filter(movie => favoriteMovies.includes(movie.id));
    const viewedMovieObjects = viewedMovies.map(id => {
        const movie = MoviesData.find(movie => movie.id === id);
        return movie ? movie : null;
    }).filter(movie => movie !== null);

    return (
        <div className={classes.favoriteContainer}>
            <section className={classes.movieSection}>
                <h2 className={classes.sectionTitle}>Избранные фильмы</h2>
                <div className={classes.movieList}>
                    {favoriteMovieObjects.length > 0 ? (
                        favoriteMovieObjects.map(movie => (
                            <div key={movie.id} className={classes.movieItem}>
                                {renderFavoriteMovie(movie)}
                            </div>
                        ))
                    ) : (
                        <p>Нет избранных фильмов.</p>
                    )}
                </div>
            </section>

            <section className={classes.movieSection}>
                <h2 className={classes.sectionTitle}>Просмотренные фильмы</h2>
                <div className={classes.movieList}>
                    {viewedMovieObjects.length > 0 ? (
                        viewedMovieObjects.map(movie => (
                            <div key={movie.id} className={classes.movieItem}>
                                {renderViewedMovie(movie)}
                            </div>
                        ))
                    ) : (
                        <p>Нет просмотренных фильмов.</p>
                    )}
                </div>
                <button className={classes.clearButton} onClick={clearViewedMovies}>Очистить историю просмотров</button>
            </section>
        </div>
    );
};

export default Favorite;