import React from 'react';
import classes from './Blog.module.scss';
import blog1 from '../../img/blog1.png';
import blog2 from '../../img/blog2.png';

const Blog = () => {
  return (
    <div className={classes.blogContainer}>
      <div className={classes.blogPost}>
        <h2>Миссия прервана: почему китайский «Лучший стрелок» так и не взлетел</h2>
        <img src={blog1} alt="Миссия прервана" className={classes.postImage} />
        <div className={classes.postInfo}>
          <span>4 420 просмотров</span>
          <span>Комментарии: 1</span>
          <a href="#">показать полностью</a>
        </div>
      </div>

      <div className={classes.blogPost}>
        <h2>Сегодня день рождения празднует американский актёр и режиссёр Стив Бушеми</h2>
        <img src={blog2} alt="Стив Бушеми" className={classes.postImage} />
        <div className={classes.postInfo}>
          <span>4 420 просмотров</span>
          <span>Комментарии: 1</span>
          <a href="#">показать полностью</a>
        </div>
      </div>
    </div>
  );
};

export default Blog;