import React from 'react'
import { Routes, Route } from "react-router-dom"
import Home from './pages/Home/Home'
import Search from './pages/Search/Search'
import AboutUs from './pages/AboutUs/AboutUs'
import Blog from './pages/Blog/Blog'
import Favorite from './pages/Favorite/Favorite'
import Login from './pages/Login/Login'
import Support from './pages/Support/Support'
import MoviePage from './pages/Film/MoviePage'


const AppRouter = () => {
  return (
    <>
      <Routes>
        <Route>
          <Route path={'/retflix/'} element={<Home />} />
          <Route path={'/retflix/MoviePage'} element={<MoviePage />} />
          <Route path={'/retflix/AboutUs'} element={<AboutUs />} />
          <Route path={'/retflix/Blog'} element={<Blog />} />
          <Route path={'/retflix/Favorite'} element={<Favorite />} />
          <Route path={'/retflix/Login'} element={<Login />} />
          <Route path={'/retflix/Search'} element={<Search />} />
          <Route path={'/retflix/Support'} element={<Support/>} />
        </Route>
      </Routes>
    </>
  )
}

export default AppRouter