import React, { useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import classes from './MoviePage.module.scss';

const MoviePage = () => {
    const location = useLocation();
    const movie = location.state?.movie;
    const navigate = useNavigate();

    useEffect(() => {
        const savedViewed = localStorage.getItem('viewed');
        let viewed = savedViewed ? JSON.parse(savedViewed) : [];

        if (movie) {
            viewed = viewed.filter(id => id !== movie.id);

            viewed.unshift(movie.id);

            localStorage.setItem('viewed', JSON.stringify(viewed));
        }
    }, [movie?.id]);

    useEffect(() => {
        if (!movie) {
            navigate('/');
        }
    }, [movie, navigate]);

    if (!movie) {
        return (
            <div>
                <h1>No movie selected</h1>
            </div>
        );
    }

    return (
        <div className={classes.moviePageContainer}>
            <div className={classes.movieHeader}>
                <div className={classes.movieInfoTop}>
                    <h1 className={classes.movieTitle}>{movie.title}</h1>
                    <div className={classes.movieDetails}>
                        <span className={classes.rating}>{movie.rating.toFixed(1)}</span>
                        <span className={classes.year}>{movie.year}</span>
                        <span className={classes.duration}>{movie.duration} мин.</span>
                        <span className={classes.ageRestriction}>{movie.ageRestriction}</span>
                    </div>
                    <p className={classes.movieDescription}>{movie.description}</p>
                </div>
                <div className={classes.moviePlayer}>
                    <img src={movie.src} alt={movie.title} className={classes.playerImage} />
                </div>
            </div>

            <div className={classes.movieInfoSection}>
                <h2>О фильме</h2>
                <div className={classes.movieFacts}>
                    <div>
                        <span className={classes.infoLabel}>Страны:</span>
                        <span>{movie.country}</span>
                    </div>
                    <div>
                        <span className={classes.infoLabel}>Жанр:</span>
                        {movie.genres.map((genre, index) => (
                            <span key={index} className={classes.genre}>{genre}{index < movie.genres.length - 1 ? ', ' : ''}</span>
                        ))}
                    </div>
                    <div>
                        <span className={classes.infoLabel}>Длительность:</span>
                        <span>{movie.duration}</span>
                    </div>
                    <div>
                        <span className={classes.infoLabel}>Год:</span>
                        <span>{movie.year}</span>
                    </div>
                    <div>
                        <span className={classes.infoLabel}>Ограничения:</span>
                        <span>{movie.ageRestriction}</span>
                    </div>
                    <div>
                        <span className={classes.infoLabel}>Язык:</span>
                        <span>{movie.language}</span>
                    </div>
                    <div>
                        <span className={classes.infoLabel}>Субтитры:</span>
                        <span>{movie.subtitles}</span>
                    </div>
                    <div>
                        <span className={classes.infoLabel}>Изображение и звук:</span>
                        <span>{movie.quality}</span>
                    </div>
                </div>
            </div>

            <div className={classes.movieInfoSection}>
                <h2>Актёры и создатели</h2>
                <div className={classes.peopleList}>
                    {movie.directors.map((director, index) => (
                        <div key={index} className={classes.person}>
                            <img src={director.photo} alt={director.name} className={classes.personImage} />
                            <span className={classes.personName}>{director.name}</span>
                            <span className={classes.personRole}>{director.role}</span>
                        </div>
                    ))}
                    {movie.actors.map((actor, index) => (
                        <div key={index} className={classes.person}>
                            <img src={actor.photo} alt={actor.name} className={classes.personImage} />
                            <span className={classes.personName}>{actor.name}</span>
                            <span className={classes.personRole}>{actor.role}</span>
                        </div>
                    ))}
                </div>
            </div>

            <div className={classes.movieInfoSection}>
                <h2>Отзывы</h2>
            </div>
        </div>
    );
};

export default MoviePage;