import React, { useRef, useEffect, useState, useCallback } from 'react';
import classes from './MovieSections.module.scss';
import { useNavigate } from 'react-router-dom';
import MoviesData from '../../MoviesData';

import heartRegular from './heart-regular.png';
import heartSolid from './heart-solid.png';

const MovieSections = () => {
    const categories = ['bestMovies', 'horrorMovies', 'actionMovies'];
    const [selectedMovie, setSelectedMovie] = useState(null);
    const navigate = useNavigate();
    const [favorites, setFavorites] = useState(() => {
        const savedFavorites = localStorage.getItem('favorites');
        try {
            return savedFavorites ? JSON.parse(savedFavorites) : [];
        } catch (error) {
            console.error("Error parsing favorites from localStorage:", error);
            return [];
        }
    });
    const [viewedMovies, setViewedMovies] = useState(() => {
        const savedViewed = localStorage.getItem('viewed');
        try {
            return savedViewed ? JSON.parse(savedViewed) : [];
        } catch (error) {
            console.error("Error parsing viewed from localStorage:", error);
            return [];
        }
    });

    const getMoviesByCategory = (category) => {
        return MoviesData.filter(movie => movie.categories.includes(category));
    };

    const handleMovieClick = (movie) => {
        setSelectedMovie(movie);
        navigate('/retflix/MoviePage', { state: { movie } });
    };

    const setLocalStorage = useCallback((key, value) => {
        localStorage.setItem(key, JSON.stringify(value));
    }, []);

    const toggleFavorite = useCallback((movieId) => {
        setFavorites(prevFavorites => {
            const isFavorite = prevFavorites.includes(movieId);
            const updatedFavorites = isFavorite
                ? prevFavorites.filter(id => id !== movieId)
                : [...prevFavorites, movieId];

            setLocalStorage('favorites', updatedFavorites);
            return updatedFavorites;
        });
    }, [setLocalStorage]);

    useEffect(() => {
        setLocalStorage('favorites', favorites)
    }, [favorites, setLocalStorage]);

    useEffect(() => {
        localStorage.setItem('viewed', JSON.stringify(viewedMovies));
    }, [viewedMovies]);


    const SimpleSlider = ({ movies }) => {
        const sliderRef = useRef(null);
        const [scrollPosition, setScrollPosition] = useState(0);

        useEffect(() => {
            const slider = sliderRef.current;

            const handleScroll = () => {
                setScrollPosition(slider.scrollLeft);
            };

            if (slider) {
                slider.addEventListener('scroll', handleScroll);

                return () => {
                    slider.removeEventListener('scroll', handleScroll);
                };
            }
        }, []);

        return (
            <div>
                <div className={classes.moviePosterSlider} ref={sliderRef}>
                    {movies.map((movie, index) => (
                        <div key={index} className={classes.moviePosterContainer}>
                            <div onClick={() => handleMovieClick(movie)} style={{ cursor: 'pointer' }}>
                                <img
                                    src={movie.src}
                                    alt={movie.title}
                                    className={classes.moviePoster}
                                />
                                <div className={classes.movieInfoOverlay}>
                                    <div className={classes.movieDetails}>
                                        <span className={classes.rating}>{movie.rating.toFixed(1)}</span>
                                        <span className={classes.year}>{movie.year}, {movie.country}</span>
                                        <span className={classes.duration}>{movie.duration} мин.</span>
                                    </div>
                                </div>
                            </div>
                            <div className={classes.favoriteIcon} onClick={(e) => {
                                e.stopPropagation();
                                toggleFavorite(movie.id);
                            }}>
                                <img
                                    src={favorites.includes(movie.id) ? heartSolid : heartRegular}
                                    alt="Favorite"
                                    className={classes.heartImage}
                                />
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );
    };

    return (
        <div className={classes.movieSectionsContainer}>
            {categories.map(category => {
                const movies = getMoviesByCategory(category);
                return (
                    <section key={category} className={classes.movieSection}>
                        <h2 className={classes.sectionTitle}>
                            {category === 'bestMovies' ? 'Лучшие фильмы' : category === 'horrorMovies' ? 'Месяц ужасов' : 'Акция'} &gt;
                        </h2>
                        <SimpleSlider movies={movies} />
                    </section>
                );
            })}
        </div>
    );
};

export default MovieSections;