import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import MoviesData from '../../MoviesData';
import classes from './Search.module.scss';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faArrowUp, faArrowDown } from '@fortawesome/free-solid-svg-icons';

const Search = () => {
    const [searchTerm, setSearchTerm] = useState('');
    const [sortByPopularity, setSortByPopularity] = useState(false);
    const [popularityOrder, setPopularityOrder] = useState('desc');
    const [filteredMovies, setFilteredMovies] = useState(MoviesData);
    const [noResults, setNoResults] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        const searchedMovies = MoviesData.filter(movie => {
            const title = movie.title.toLowerCase();
            const description = movie.description.toLowerCase();
            const term = searchTerm.toLowerCase();

            return title.includes(term) || description.includes(term);
        });

        let sortedMovies = [...searchedMovies];
        if (sortByPopularity) {
            sortedMovies.sort((a, b) => {
                if (popularityOrder === 'asc') {
                    return a.rating - b.rating;
                } else {
                    return b.rating - a.rating;
                }
            });
        }

        setFilteredMovies(sortedMovies);
        setNoResults(searchedMovies.length === 0 && searchTerm !== '');
    }, [searchTerm, sortByPopularity, popularityOrder]);

    const handleSearchChange = (event) => {
        setSearchTerm(event.target.value);
    };

    const handleSortChange = () => {
        setSortByPopularity(!sortByPopularity);
        setPopularityOrder(popularityOrder === 'asc' ? 'desc' : 'asc');
    };

    const handleMovieClick = (movie) => {
        navigate('/MoviePage', { state: { movie } });
    };

    return (
        <div className={classes.searchContainer}>
            <div className={classes.searchHeader}>
                <input
                    type="text"
                    placeholder="Поиск"
                    value={searchTerm}
                    onChange={handleSearchChange}
                    className={classes.searchInput}
                />
                <div className={classes.sortButton} onClick={handleSortChange}>
                    Популярное
                    <FontAwesomeIcon
                        icon={popularityOrder === 'asc' ? faArrowUp : faArrowDown}
                        className={classes.sortArrow}
                    />
                </div>
            </div>

            <div className={classes.movieList}>
                {noResults ? (
                    <div className={classes.noResultsMessage}>
                        Нет результатов для "{searchTerm}"
                    </div>
                ) : (
                    filteredMovies.map(movie => (
                        <div
                            key={movie.id}
                            className={classes.movieItem}
                            onClick={() => handleMovieClick(movie)}
                        >
                            <img src={movie.src} alt={movie.title} className={classes.moviePoster} />
                            <div className={classes.movieDetails}>
                                <div className={classes.movieInfo}>
                                    <span className={classes.movieRating}>{movie.rating}</span>
                                    <span>{movie.year}</span>
                                    <span>{movie.duration} мин.</span>
                                    <span>{movie.ageRestriction}</span>
                                </div>
                                <p className={classes.movieDescription}>{movie.description}</p>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
};

export default Search;