import React from 'react';
import classes from './Header.module.scss';
import { useNavigate } from 'react-router-dom';
import logo from './Logo.svg'

const Header = () => {
  const navigate = useNavigate();

  return (
    <header className={classes.header}>
      <p onClick={() => navigate('/retflix/Search')}>Поиск</p>
      <p onClick={() => navigate('/retflix/Favorite')}>Любимое</p>
      <p onClick={() => navigate('/retflix/Blog')}>Блог</p>
      <img onClick={() => navigate('/retflix/')} src={logo} alt="Logo" className={classes.logo} />
      <p onClick={() => navigate('/retflix/AboutUs')}>О нас</p>
      <p onClick={() => navigate('/retflix/Support')}>Поддержка</p>
      <p onClick={() => navigate('/retflix/Login')}>Вход</p>
    </header>
  );
};

export default Header;