import React from 'react';
import classes from './Login.module.scss';

const Login = () => {
    return (
        <div className={classes.loginContainer}>
            <div className={classes.loginSection}>
                <div className={classes.qrCodeSection}>
                    <img src="./img/qr-code 1.png" alt="QR Code" className={classes.qrCode} />
                    <p>Сканируйте QR для быстрого входа</p>
                </div>
                <div className={classes.separator}>или</div>
                <div className={classes.loginForm}>
                    <input type="text" placeholder="Логин" className={classes.inputField} />
                    <input type="password" placeholder="Пароль" className={classes.inputField} />
                    <button className={classes.loginButton}>Вход</button>
                    <a href="#" className={classes.registerLink}>Регистрация</a>
                </div>
            </div>

            <div className={classes.subscriptionsSection}>
                <h2>Подписки</h2>
                <p>Дают доступ к каталогу лучших фильмов, сериалов и мультфильмов.</p>

                <div className={classes.subscriptionsGrid}>
                    <div className={classes.subscriptionCard}>
                        <img src="./img/Frame 25.png" alt="Subscription 1" className={classes.subscriptionImage} />
                        <div className={classes.subscriptionContent}>
                            <h3>Подписка</h3>
                            <p>Доступ к платным фильмам и сериалам для 1 человека</p>
                            <button className={classes.cancelButton}>Отказаться от подписки (99руб/мес.)</button>
                        </div>
                    </div>

                    <div className={classes.subscriptionCard}>
                        <img src="./img/Frame 25.png" alt="Subscription 2" className={classes.subscriptionImage} />
                        <div className={classes.subscriptionContent}>
                            <h3>Мульти-Подписка</h3>
                            <p>Доступ к платным фильмам и сериалам до 5 человек</p>
                            <button className={classes.subscribeButton}>Подключить от 199руб/мес.</button>
                        </div>
                    </div>

                    <div className={classes.subscriptionCard}>
                        <img src="./img/Frame 25.png" alt="Subscription 3" className={classes.subscriptionImage} />
                        <div className={classes.subscriptionContent}>
                            <h3>Подписка + Amediateka</h3>
                            <p>Расширенный каталог</p>
                            <button className={classes.subscribeButton}>Подключить от 299руб/мес.</button>
                        </div>
                    </div>

                    <div className={classes.subscriptionCard}>
                        <img src="./img/Frame 25.png" alt="Subscription 4" className={classes.subscriptionImage} />
                        <div className={classes.subscriptionContent}>
                            <h3>Подписка + Start</h3>
                            <p>Расширенный каталог</p>
                            <button className={classes.subscribeButton}>Подключить от 299руб/мес.</button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Login;